export async function searchTicketing(db: Db, phrase: UntrustedInput): Promise<void> {
  const statement = `
    SELECT id, subject
    FROM ticketing
    WHERE subject ILIKE '%` + phrase + `%'
  `;
  await db.query(statement);
}

